import std.io

foreign "c" {
    record Box { }
    fn boxInt(v: Int64) effect -> Box
    fn unboxInt(b: Box) effect -> Int64
}

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let b = boxInt(41)
    let n = unboxInt(b)
    if n == 41 {
        io.println("unboxed")
    } else {
        io.println("bad")
    }
    return Ok(())
}

